-- READ ONLY. Mission 001A ordinary-client privilege containment verification. Run each SELECT independently.
-- 1. Exact tables and aggregate row counts only.
select t.name,to_regclass('public.'||t.name) object from (values('openingfit_missions'),('openingfit_mission_training_attempts'),('openingfit_mission_encounters'),('openingfit_mission_status_events')) t(name) order by 1;
select 'openingfit_missions' table_name,count(*) row_count from public.openingfit_missions union all select 'openingfit_mission_training_attempts',count(*) from public.openingfit_mission_training_attempts union all select 'openingfit_mission_encounters',count(*) from public.openingfit_mission_encounters union all select 'openingfit_mission_status_events',count(*) from public.openingfit_mission_status_events order by 1;
-- 2. RLS and policies.
select c.relname,c.relrowsecurity,c.relforcerowsecurity from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events']) order by 1;
select tablename,policyname,roles,cmd,qual,with_check from pg_policies where schemaname='public' and tablename=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events']) order by 1,2;
-- 3. Effective privileges. Every has_privilege value must be false.
select r.name role_name,t.name table_name,p.name privilege,has_table_privilege(r.oid,to_regclass('public.'||t.name),p.name) has_privilege from (values('openingfit_missions'),('openingfit_mission_training_attempts'),('openingfit_mission_encounters'),('openingfit_mission_status_events')) t(name) cross join (values(0::oid,'PUBLIC'),('anon'::regrole::oid,'anon'),('authenticated'::regrole::oid,'authenticated')) r(oid,name) cross join (values('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')) p(name) order by 1,2,3;
-- 4. No Mission functions or non-internal triggers.
select n.nspname,p.proname,pg_get_function_identity_arguments(p.oid) arguments from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like '%openingfit_mission%' order by 2,3;
select c.relname,t.tgname from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events']) and not t.tgisinternal order by 1,2;
-- 5. Exact constraints and indexes remain available for definition review.
select c.conrelid::regclass,c.conname,c.contype,pg_get_constraintdef(c.oid) definition from pg_constraint c where c.conrelid=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events']::regclass[]) order by 1,2;
select tablename,indexname,indexdef from pg_indexes where schemaname='public' and tablename=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events']) order by 1,2;
-- 6. containment_absent requires the preserved pre-containment state with forbidden privileges on every table.
with checks as (select ((select count(*) from pg_class r join pg_namespace n on n.oid=r.relnamespace where n.nspname='public' and r.relkind='r' and r.relname=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events']))=4 and (select count(*)=8 and md5(string_agg(tablename||'|'||indexname||'|'||indexdef,chr(10) order by indexname))='7f724464ada49aa0ddca4f128d419715' from pg_indexes where schemaname='public' and indexname=any(array['openingfit_missions_one_primary_active_idx','openingfit_missions_current_lookup_idx','openingfit_missions_history_idx','openingfit_missions_position_idx','openingfit_missions_source_report_idx','openingfit_mission_attempts_history_idx','openingfit_mission_encounters_verification_idx','openingfit_mission_status_events_history_idx'])) and (select count(*)=46 and md5(string_agg(n.nspname||'.'||r.relname||'|'||c.conname||'|'||c.contype::text||'|'||pg_get_constraintdef(c.oid,false),chr(10) order by n.nspname,r.relname,c.conname))='cb93fc8e4263fd7b74d89d8fc1527d02' from pg_constraint c join pg_class r on r.oid=c.conrelid join pg_namespace n on n.oid=r.relnamespace where n.nspname='public' and r.relname=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events'])) and (select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events']) and c.relrowsecurity)=4 and (select count(*) from public.openingfit_missions)+(select count(*) from public.openingfit_mission_training_attempts)+(select count(*) from public.openingfit_mission_encounters)+(select count(*) from public.openingfit_mission_status_events)=0 and not exists(select 1 from pg_policies where schemaname='public' and tablename=any(array['openingfit_missions','openingfit_mission_training_attempts','openingfit_mission_encounters','openingfit_mission_status_events'])) and not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like '%openingfit_mission%') and not exists(select 1 from pg_trigger t where t.tgrelid=any(array[to_regclass('public.openingfit_missions'),to_regclass('public.openingfit_mission_training_attempts'),to_regclass('public.openingfit_mission_encounters'),to_regclass('public.openingfit_mission_status_events')]) and not t.tgisinternal)) preserved,((select count(*) from (values('openingfit_missions'),('openingfit_mission_training_attempts'),('openingfit_mission_encounters'),('openingfit_mission_status_events')) t(name) where exists(select 1 from (values(0::oid),('anon'::regrole::oid),('authenticated'::regrole::oid)) r(oid) cross join (values('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')) p(name) where has_table_privilege(r.oid,to_regclass('public.'||t.name),p.name)))=4) absent,(not exists(select 1 from (values('openingfit_missions'),('openingfit_mission_training_attempts'),('openingfit_mission_encounters'),('openingfit_mission_status_events')) t(name) cross join (values(0::oid),('anon'::regrole::oid),('authenticated'::regrole::oid)) r(oid) cross join (values('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')) p(name) where has_table_privilege(r.oid,to_regclass('public.'||t.name),p.name))) complete) select case when preserved and absent then 'containment_absent' when preserved and complete then 'containment_complete' else 'containment_partial' end classification from checks;
